#!/usr/bin/env python3
"""Configure this decompilation project (generated by romwright new-project).

    python3 configure.py                # fetch tools, write asm/header.s, the link script and build.ninja
    python3 configure.py swap NAME      # turn one assembly function into a C unit

The unit table is config/units.json: the whole ROM, in order, as header, assembly
(`asm`), retail-bytes (`data`) and C (`c`) units. `ninja` assembles/compiles each
unit, links them in order at the retail addresses, flattens the link to a ROM
and compares its sha1 with config/checksum.sha1.
"""
import argparse
import json
import os
import re
import shlex
import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
sys.path.insert(0, str(ROOT / "tools"))
import download_tool  # noqa: E402

PROJECT = json.loads((ROOT / "config" / "project.json").read_text())
NAME = PROJECT["image"]["file"]
BASE = PROJECT["image"]["base"]
BUILD = ROOT / "build"
UNITS = ROOT / "config" / "units.json"
LOCAL_PROFILE = ROOT / "config" / "toolchain.local.json"


# --------------------------------------------------------------------------
# Tools
# --------------------------------------------------------------------------

def load_profile(path):
    profile = json.loads(Path(path).read_text())
    for key, entry in (profile.get("tools") or {}).items():
        digest = (entry.get("digest") or "").lower()
        if digest and len(digest) == 64:
            actual = download_tool.sha256_file(entry["path"])
            if actual != digest:
                raise SystemExit(f"{path}: tool `{key}` ({entry['path']}) sha256 {actual} != profile digest {digest}")
    return profile


def member(install_dir, pattern):
    """First file below `install_dir` matching the manifest's member glob (archives
    carry a version-named top directory, so the manifest names `*/bin/...`)."""
    found = sorted(Path(install_dir).glob(pattern))
    if not found:
        raise SystemExit(f"{install_dir}: no file matches `{pattern}` (a changed archive layout? check config/toolchain.json)")
    return str(found[0])


def resolve_tools(args):
    manifest = download_tool.load_manifest(args.manifest or ROOT / "config" / "toolchain.json")
    spec = PROJECT["tools"]
    profile_path = args.toolchain or (LOCAL_PROFILE if LOCAL_PROFILE.exists() else None)
    profile = load_profile(profile_path) if profile_path else {}
    given = {key: entry["path"] for key, entry in (profile.get("tools") or {}).items()}
    paths = {}

    def where(tool_id):
        if args.no_tools:
            return BUILD / "tools" / tool_id
        return download_tool.install(manifest[tool_id], BUILD / "tools", BUILD / "tools" / ".cache")

    binutils = manifest[spec["binutils"]]
    installed = None
    for key, pattern in binutils["provides"].items():
        if key in given:
            paths[key] = given[key]
            continue
        installed = installed or where(binutils["id"])
        paths[key] = member(installed, pattern)
    compiler = manifest[spec["compiler"]]
    if "compiler" in given:
        paths["agbcc"] = given["compiler"]
    else:
        paths["agbcc"] = member(where(compiler["id"]), compiler["entry"])
    paths["agbcc_include"] = str(Path(paths["agbcc"]).parent.parent / "include")
    if "objdiff-cli" in given:
        paths["objdiff-cli"] = given["objdiff-cli"]
    elif spec.get("report") and not args.no_tools:
        try:
            paths["objdiff-cli"] = member(where(spec["report"]), "objdiff-cli*")
        except SystemExit as error:
            print(f"warning: objdiff-cli unavailable ({error}); `ninja progress` is disabled", file=sys.stderr)
    BUILD.mkdir(exist_ok=True)
    (BUILD / "tools.json").write_text(json.dumps(paths, indent=2) + "\n")
    return paths


# --------------------------------------------------------------------------
# Units
# --------------------------------------------------------------------------

def load_units():
    return json.loads(UNITS.read_text())


def stem_of(unit):
    return Path(unit["source"]).stem


def object_of(unit):
    """Object path of a unit. Assembly and data units share one directory per run
    (one wildcard statement in the link script); C units live apart so a wildcard
    never picks them up."""
    if unit["kind"] == "header":
        return "build/obj/header.o"
    if unit["kind"] == "c":
        return f"build/obj/c/{unit['dir']}/{stem_of(unit)}.o"
    return f"build/obj/{unit['dir']}/{stem_of(unit)}.o"


def link_script(units):
    """GNU ld script: one statement per run of assembly/data units of a directory
    (GNU ld is cubic in `file(.section)` statements), and a statement of its own for
    every C unit, with the location counter pinned to the unit's slot."""
    out = [
        "OUTPUT_ARCH(arm)",
        "SECTIONS",
        "{",
        f"  .rom {BASE:#x} : SUBALIGN(1)",
        "  {",
    ]
    index = 0
    while index < len(units):
        unit = units[index]
        if unit["kind"] == "c":
            out.append(f"    . = {unit['start'] - BASE:#x};")
            out.append(f"    *{object_of(unit)[len('build/'):]}(.text)")
            out.append(f"    . = {unit['end'] - BASE:#x};")
            index += 1
            continue
        if unit["kind"] == "header":
            out.append(f"    *{object_of(unit)[len('build/'):]}(.text)")
            index += 1
            continue
        run = index
        while run + 1 < len(units) and units[run + 1]["kind"] in ("asm", "data") and units[run + 1]["dir"] == unit["dir"]:
            run += 1
        if run == index:
            out.append(f"    *{object_of(unit)[len('build/'):]}(.text)")
        else:
            out.append(f"    *obj/{unit['dir']}/*.o(.text)")
        # Pins the location counter (inside an output section `.` is an offset from its start): a run that overshoots stops the link ("cannot move
        # location counter backwards") instead of shifting everything after it.
        out.append(f"    . = {units[run]['end'] - BASE:#x};")
        index = run + 1
    out += ["  }", "  /DISCARD/ : { *(*) }", "}", ""]
    return "\n".join(out)


# --------------------------------------------------------------------------
# build.ninja / objdiff.json
# --------------------------------------------------------------------------

def esc(path):
    return str(path).replace("$", "$$").replace(" ", "$ ").replace(":", "$:")


class Ninja:
    def __init__(self, handle):
        self.out = handle

    def var(self, key, value):
        self.out.write(f"{key} = {value}\n")

    def rule(self, name, command, description, **extra):
        self.out.write(f"rule {name}\n  command = {command}\n  description = {description}\n")
        for key, value in extra.items():
            self.out.write(f"  {key} = {value}\n")
        self.out.write("\n")

    def build(self, outputs, rule, inputs=(), implicit=(), variables=None):
        line = f"build {' '.join(esc(o) for o in outputs)}: {rule} {' '.join(esc(i) for i in inputs)}"
        if implicit:
            line += " | " + " ".join(esc(i) for i in implicit)
        self.out.write(line + "\n")
        for key, value in (variables or {}).items():
            self.out.write(f"  {key} = {value}\n")
        self.out.write("\n")


def quote(argv):
    return " ".join(shlex.quote(str(a)).replace("$", "$$") for a in argv)


def headers():
    include = ROOT / "include"
    return sorted(str(p.relative_to(ROOT)) for p in include.rglob("*.h")) if include.exists() else []


def write_build(paths, units):
    with open(ROOT / "build.ninja", "w") as handle:
        n = Ninja(handle)
        n.var("ninja_required_version", "1.7")
        n.var("python", shlex.quote(sys.executable))
        n.out.write("\n")
        scratch = BUILD / "tmp"
        scratch.mkdir(parents=True, exist_ok=True)
        env_prefix = f"env TMPDIR={shlex.quote(str(scratch))} "
        asflags = quote(PROJECT["compiler"]["asflags"])
        n.rule("as", "$python tools/asm.py $out $in", "as $in")
        n.rule("as_data", f"{quote([paths['as']])} {asflags} -I include -o $out $in", "as $in")
        n.rule("cc", env_prefix + "$python tools/cc.py $out $in", "cc $in")
        n.rule("header", "$python tools/header.py", "header")
        n.rule("autosyms", "$python tools/autosyms.py $out $in", "autosyms")
        n.rule("ld", f"{quote([paths['ld']])} -T ld_script.ld -T config/symbols.ld -T build/autosyms.ld --no-check-sections --no-warn-rwx-segments -o $out @$out.rsp",
               "link $out", rspfile="$out.rsp", rspfile_content="$in")
        n.rule("objcopy", f"{quote([paths['objcopy']])} -O binary $in $out", "rom $out")
        n.rule("verify", "$python tools/verify.py $in config/checksum.sha1 $out", "verify $in")
        n.rule("report", f"{quote([paths.get('objdiff-cli', 'objdiff-cli')])} report generate -o $out", "report")
        objects = []
        c_units = []
        n.build(["asm/header.s"], "header", [], implicit=["config/header.json", "tools/header.py"])
        for unit in units:
            obj = object_of(unit)
            objects.append(obj)
            if unit["kind"] == "header":
                n.build([obj], "as_data", [unit["source"]], implicit=["asm/header.s"])
            elif unit["kind"] == "data":
                n.build([obj], "as_data", [unit["source"]])
            elif unit["kind"] == "asm":
                n.build([obj], "as", [unit["source"]], implicit=["tools/asm.py", "config/project.json", "include/macro.inc"])
            else:
                n.build([obj], "cc", [unit["source"]], implicit=headers() + ["tools/cc.py", "config/project.json"])
                c_units.append(unit)
        n.build(["build/autosyms.ld"], "autosyms", [object_of(u) for u in c_units], implicit=["tools/autosyms.py"])
        n.build([f"build/{NAME}.elf"], "ld", objects, implicit=["ld_script.ld", "config/symbols.ld", "build/autosyms.ld"])
        n.build([f"build/{NAME}"], "objcopy", [f"build/{NAME}.elf"])
        n.build([f"build/{NAME}.ok"], "verify", [f"build/{NAME}"], implicit=["config/checksum.sha1", "config/units.json"])
        targets = []
        for unit in c_units:
            target = f"build/target/{stem_of(unit)}.o"
            n.build([target], "as", [unit["retail_source"]], implicit=["tools/asm.py", "config/project.json"])
            targets.append(target)
        if "objdiff-cli" in paths:
            n.build(["build/report.json"], "report", [], implicit=[object_of(u) for u in c_units] + targets + ["objdiff.json"])
            n.build(["progress"], "phony", ["build/report.json"])
        n.build(["all"], "phony", [f"build/{NAME}.ok"])
        n.out.write("default all\n")


def write_objdiff(units):
    rows = []
    for unit in units:
        if unit["kind"] != "c":
            continue
        rows.append({
            "name": stem_of(unit),
            "target_path": f"build/target/{stem_of(unit)}.o",
            "base_path": object_of(unit),
            "metadata": {"complete": False, "auto_generated": False, "source_path": unit["source"]},
        })
    document = {
        "min_version": "2.0.0-beta.5",
        "custom_make": "ninja",
        "build_target": True,
        "build_base": True,
        "watch_patterns": ["src/**/*.c", "include/**/*.h", "config/**"],
        "units": rows,
    }
    (ROOT / "objdiff.json").write_text(json.dumps(document, indent=2) + "\n")


# --------------------------------------------------------------------------
# swap
# --------------------------------------------------------------------------

def swap(args):
    units = load_units()
    target = args.function
    if re.fullmatch(r"0x[0-9a-fA-F]+", target):
        address = int(target, 16)
        found = [u for u in units if u["kind"] == "asm" and u["start"] == address]
    else:
        found = [u for u in units if u["kind"] == "asm" and u["name"] == target]
    if not found:
        raise SystemExit(f"`{args.function}` is not an assembly unit of config/units.json (already a C unit, or not a function entry?)")
    unit = found[0]
    index = units.index(unit)
    # Entries after it in the same directory move to a new directory: their objects
    # stay one contiguous run for the link script's wildcard.
    used = {u["dir"] for u in units}
    n = 2
    while f"{unit['dir']}_{n}" in used:
        n += 1
    for later in units[index + 1:]:
        if later["kind"] not in ("asm", "data") or later["dir"] != unit["dir"]:
            break
        later["dir"] = f"{unit['dir']}_{n}"
    unit["retail_source"] = unit["source"]
    unit["kind"] = "c"
    unit["source"] = f"src/{Path(unit['source']).relative_to('asm').with_suffix('.c')}"
    UNITS.write_text(json.dumps(units, indent=2) + "\n")
    destination = ROOT / unit["source"]
    destination.parent.mkdir(parents=True, exist_ok=True)
    if args.src:
        shutil.copyfile(args.src, destination)
    elif not destination.exists():
        reference = ROOT / "decompiled" / f"{unit['name']}.c"
        body = reference.read_text() if reference.exists() else "/* write the C for this function; it must compile to exactly the retail bytes */\n"
        destination.write_text('#include "romwright_types.h"\n\n' + body if not body.startswith("#include") else body)
    print(f"{unit['name']}: assembly -> C unit {unit['source']}")


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--toolchain", help="toolchain profile JSON (replaces manifest tools one by one)")
    parser.add_argument("--manifest", help="tool manifest (default config/toolchain.json)")
    parser.add_argument("--no-tools", action="store_true", help="do not download; use what is already in build/tools")
    sub = parser.add_subparsers(dest="command")
    swap_parser = sub.add_parser("swap", help="turn one assembly function into a C unit")
    swap_parser.add_argument("function", help="function name or 0xADDRESS")
    swap_parser.add_argument("--src", help="C file to install as the unit")
    args = parser.parse_args()
    if args.command == "swap":
        swap(args)
    paths = resolve_tools(args)
    subprocess.run([sys.executable, str(ROOT / "tools" / "header.py")], check=True, cwd=ROOT)
    units = load_units()
    (ROOT / "ld_script.ld").write_text(link_script(units))
    write_build(paths, units)
    write_objdiff(units)
    print(f"configured: {len(units)} units, {sum(1 for u in units if u['kind'] == 'c')} C unit(s); run `ninja`")


if __name__ == "__main__":
    main()
